'use client';

import React, { useState } from 'react';

export default function AgenticScreen() {
  const [activeNode, setActiveNode] = useState(0);
  const nodes = [
    { title: 'Supervisor Node', desc: 'LangGraph Router', role: 'Decomposing task' },
    { title: 'Worker Agent', desc: 'Mistral SQL FT', role: 'Generating self-healing SQL' },
    { title: 'Evaluation Guard', desc: 'DeepEval Interceptor', role: 'Zero hallucination check' },
  ];

  const handleStep = () => {
    setActiveNode((prev) => (prev + 1) % nodes.length);
  };

  return (
    <div className="screen-panel">
      <div style={{ marginBottom: '10px' }}>
        <span style={{ fontSize: '0.68rem', color: '#64748b', textTransform: 'uppercase', display: 'block' }}>
          MULTI-AGENT ORCHESTRATION GRAPH
        </span>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.84rem', color: '#f8fafc', fontWeight: 600 }}>
          Stateful Swarms &amp; Autonomous Fallbacks
        </span>
      </div>

      <div className="swarm-dag-container">
        {nodes.map((n, i) => (
          <React.Fragment key={n.title}>
            <div className={`swarm-node ${activeNode === i ? 'active-pulse' : ''}`}>
              <div className="swarm-node-title">{n.title}</div>
              <div className="swarm-node-sub">{n.desc}</div>
            </div>
            {i < nodes.length - 1 && <span className="swarm-connector-arrow">➔</span>}
          </React.Fragment>
        ))}
      </div>

      <div className="terminal-stream-box" style={{ marginTop: '12px', flex: 'none', height: '95px' }}>
        <div className="terminal-line">
          <span className="terminal-prompt" style={{ color: '#c084fc' }}>swarm://dag $</span>
          <span>exec --subgraph=flipkart_talk2data</span>
        </div>
        <div style={{ color: '#c084fc', fontSize: '0.72rem', marginTop: '4px' }}>
          &gt; Current Step [{activeNode + 1}/3]: {nodes[activeNode].role}
        </div>
        <div style={{ textAlign: 'right', marginTop: '6px' }}>
          <button
            onClick={handleStep}
            style={{
              padding: '3px 8px',
              fontSize: '0.68rem',
              background: 'rgba(168, 85, 247, 0.15)',
              border: '1px solid rgba(168, 85, 247, 0.3)',
              color: '#c084fc',
              borderRadius: '6px',
              cursor: 'pointer',
              fontFamily: 'var(--font-mono)',
            }}
          >
            ⚡ Step DAG Execution
          </button>
        </div>
      </div>
    </div>
  );
}
