'use client';

import React, { useEffect, useRef, useState } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import ProductStage from './ProductStage';

export default function ScrollStorySection() {
  const containerRef = useRef(null);
  const cardNodeRef = useRef(null);
  const [activeActIndex, setActiveActIndex] = useState(0);

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);

    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const isMobile = window.innerWidth < 768;

    const ctx = gsap.context(() => {
      const card = document.getElementById('product-card-3d');
      if (!card) return;

      // Master scrubbed timeline across the 500vh scroll track
      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: containerRef.current,
          start: 'top top',
          end: 'bottom bottom',
          scrub: 1,
          onUpdate: (self) => {
            const p = self.progress;
            let act = 0;
            if (p < 0.16) act = 0;
            else if (p < 0.38) act = 1;
            else if (p < 0.60) act = 2;
            else if (p < 0.82) act = 3;
            else act = 4;

            setActiveActIndex(act);

            // Instant DOM panel and tab toggle for snappy 60fps scrubbing
            const panels = [
              document.getElementById('panel-hero'),
              document.getElementById('panel-rag'),
              document.getElementById('panel-agentic'),
              document.getElementById('panel-voice'),
              document.getElementById('panel-video'),
            ];
            panels.forEach((pnl, idx) => {
              if (pnl) pnl.classList.toggle('active', idx === act);
            });
            const tabs = document.querySelectorAll('.device-tab');
            tabs.forEach((tab, idx) => {
              if (tab) tab.classList.toggle('active', idx === act);
            });
          },
        },
      });

      // Text act cards crossfade choreography
      const act0 = document.getElementById('story-text-0');
      const act1 = document.getElementById('story-text-1');
      const act2 = document.getElementById('story-text-2');
      const act3 = document.getElementById('story-text-3');
      const act4 = document.getElementById('story-text-4');

      if (prefersReducedMotion) {
        gsap.set(card, { scale: 1, x: 0, y: 0 });
        return;
      }

      // Initial States
      gsap.set(card, {
        x: '0vw',
        y: '8vh',
        scale: 1.0,
        rotateY: 0,
        rotateX: 4,
        rotateZ: 0,
      });

      // Setup Text Act Opacity & Positions
      gsap.set(act0, { opacity: 1, y: 0 });
      gsap.set([act1, act2, act3, act4], { opacity: 0, y: 30, pointerEvents: 'none' });

      if (isMobile) {
        // Mobile: card stays central while text crossfades
        tl.to(act0, { opacity: 0, y: -20, duration: 1 })
          .to(card, { scale: 0.85, y: '-2vh', duration: 1 }, '<')
          .to(act1, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1 })
          .to(act1, { opacity: 0, y: -20, pointerEvents: 'none', duration: 1 }, '+=0.5')
          .to(act2, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1 })
          .to(act2, { opacity: 0, y: -20, pointerEvents: 'none', duration: 1 }, '+=0.5')
          .to(act3, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1 })
          .to(act3, { opacity: 0, y: -20, pointerEvents: 'none', duration: 1 }, '+=0.5')
          .to(act4, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1 });
      } else {
        // Desktop Full Cinematic 3D Scrubbing

        // Phase 1: Hero -> Act 1 (RAG)
        // Card slides to right (x: +22vw), tilts slightly; Hero text fades out, RAG text fades in on left
        tl.to(act0, { opacity: 0, y: -30, pointerEvents: 'none', duration: 1.5, ease: 'power2.inOut' })
          .to(
            card,
            {
              x: '21vw',
              y: '0vh',
              scale: 0.82,
              rotateY: -10,
              rotateX: 3,
              rotateZ: -1,
              duration: 2,
              ease: 'power2.inOut',
            },
            '<'
          )
          .to(act1, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1.5, ease: 'power2.out' }, '-=0.5')

          // Pause briefly on Act 1
          .to({}, { duration: 1 })

          // Phase 2: Act 1 (RAG) -> Act 2 (Agentic Swarms)
          // Card flips across Y to left side (x: -21vw), tilts; RAG text fades out, Swarm text fades in on right
          .to(act1, { opacity: 0, y: -30, pointerEvents: 'none', duration: 1.5, ease: 'power2.inOut' })
          .to(
            card,
            {
              x: '-21vw',
              y: '-1vh',
              scale: 0.80,
              rotateY: 12,
              rotateX: -2,
              rotateZ: 1.5,
              duration: 2.2,
              ease: 'power2.inOut',
            },
            '<'
          )
          .to(act2, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1.5, ease: 'power2.out' }, '-=0.5')

          // Pause briefly on Act 2
          .to({}, { duration: 1 })

          // Phase 3: Act 2 (Agentic) -> Act 3 (Voice AI)
          // Card glides back to right side (x: +20vw); Swarm text fades out, Voice text fades in on left
          .to(act2, { opacity: 0, y: -30, pointerEvents: 'none', duration: 1.5, ease: 'power2.inOut' })
          .to(
            card,
            {
              x: '21vw',
              y: '0vh',
              scale: 0.84,
              rotateY: -8,
              rotateX: 3,
              rotateZ: -1,
              duration: 2.2,
              ease: 'power2.inOut',
            },
            '<'
          )
          .to(act3, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1.5, ease: 'power2.out' }, '-=0.5')

          // Pause briefly on Act 3
          .to({}, { duration: 1 })

          // Phase 4: Act 3 (Voice) -> Act 4 (Veo Video Studio)
          // Card expands and centers (x: 0vw, scale: 0.95); Voice text fades out, Video text fades in on right
          .to(act3, { opacity: 0, y: -30, pointerEvents: 'none', duration: 1.5, ease: 'power2.inOut' })
          .to(
            card,
            {
              x: '0vw',
              y: '10vh',
              scale: 0.92,
              rotateY: 0,
              rotateX: 2,
              rotateZ: 0,
              duration: 2.2,
              ease: 'power2.inOut',
            },
            '<'
          )
          .to(act4, { opacity: 1, y: 0, pointerEvents: 'auto', duration: 1.5, ease: 'power2.out' }, '-=0.5')

          // Hold slightly at end before transitioning to systems
          .to({}, { duration: 1 });
      }

      // Smooth background color interpolation with scroll
      const bgColors = ['#07090e', '#051417', '#0c0a1a', '#150d06', '#070e1b'];
      ScrollTrigger.create({
        trigger: containerRef.current,
        start: 'top top',
        end: 'bottom bottom',
        scrub: 1.2,
        onUpdate: (self) => {
          const idx = Math.min(Math.floor(self.progress * bgColors.length), bgColors.length - 1);
          document.body.style.backgroundColor = bgColors[idx];
        },
      });
    }, containerRef);

    return () => ctx.revert();
  }, []);

  return (
    <div ref={containerRef} className="story-scroll-track" id="story-track">
      {/* Pinned Viewport: Stays locked in view for the entire 500vh scroll */}
      <div className="sticky-story-viewport">
        {/* Pinned 3D Hardware Device Experience */}
        <ProductStage activeActIndex={activeActIndex} onSelectMode={(idx) => setActiveActIndex(idx)} />

        {/* Editorial Text Layer (Positioned side-by-side with 3D product) */}
        <div className="container-custom story-text-overlay">
          {/* Act 0: Hero Editorial (Centered at top) */}
          <div className="story-editorial-wrapper align-center" id="story-text-0">
            <div className="hero-editorial-header">
              <div className="glass-pill" style={{ marginBottom: '16px' }}>
                <span className="pulse-dot"></span>
                <span>AVAILABLE FOR NEW ROLES · APPLIED AI ENGINEER</span>
              </div>
              <h1 className="hero-main-title">
                I'm <span className="text-glow-cyan">Shreyans Jain</span>
              </h1>
              <p className="hero-main-tagline">
                Builder of Autonomous Agent Swarms, Low-Latency Voice AI &amp; Enterprise RAG at{' '}
                <strong style={{ color: '#ffffff' }}>dentsu</strong>.
              </p>
              <div style={{ display: 'flex', gap: '14px', justifyContent: 'center', marginTop: '18px', flexWrap: 'wrap' }}>
                <a href="#act-systems" className="btn-primary">
                  Explore Shipped Systems ↓
                </a>
                <a
                  href="https://github.com/Shreyyyyy?tab=repositories"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="btn-secondary"
                >
                  GitHub Repos ↗
                </a>
              </div>
              <div className="scroll-hint-pill">
                <span>Scroll down to experience the product evolution</span>
                <span className="scroll-arrow-down">↓</span>
              </div>
            </div>
          </div>

          {/* Act 1: RAG & Knowledge Systems (Left aligned) */}
          <div className="story-editorial-wrapper align-left" id="story-text-1">
            <div className="story-editorial-card">
              <div className="story-badge emerald">
                <span>🔍 ACT 01 · KNOWLEDGE SYSTEMS</span>
              </div>
              <h2 className="story-headline">
                Enterprise RAG.<br />
                <span className="text-glow-emerald">60+ Mins to &lt;1 Min.</span>
              </h2>
              <p className="story-copy">
                Architecting hybrid retrieval engines that unite dense semantic embeddings with BM25 sparse lexical
                search. Slashes lookup time across 100+ page technical manuals with 98.4% groundedness.
              </p>
              <div className="story-highlight-stats">
                <div>
                  <span className="story-stat-num text-glow-emerald">&lt;60s</span>
                  <span className="story-stat-label">Lookup Speed</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-cyan">98.4%</span>
                  <span className="story-stat-label">Faithfulness</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-gold">Hybrid</span>
                  <span className="story-stat-label">Dense + BM25</span>
                </div>
              </div>
            </div>
          </div>

          {/* Act 2: Agentic AI & Swarms (Right aligned) */}
          <div className="story-editorial-wrapper align-right" id="story-text-2">
            <div className="story-editorial-card">
              <div className="story-badge purple">
                <span>🤖 ACT 02 · AGENTIC SWARMS</span>
              </div>
              <h2 className="story-headline">
                Autonomous Swarms.<br />
                <span className="text-glow-purple">Self-Healing Workflows.</span>
              </h2>
              <p className="story-copy">
                Orchestrating stateful multi-agent DAGs using LangGraph and Google ADK. Built Flipkart Talk2Data:
                translating natural language into self-reflecting, zero-shot SQL queries with &lt;2% error loop.
              </p>
              <div className="story-highlight-stats">
                <div>
                  <span className="story-stat-num text-glow-purple">&lt;2%</span>
                  <span className="story-stat-label">SQL Error Loop</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-cyan">+30%</span>
                  <span className="story-stat-label">Fine-Tuned Precision</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-emerald">LangGraph</span>
                  <span className="story-stat-label">State Machines</span>
                </div>
              </div>
            </div>
          </div>

          {/* Act 3: Voice AI & Audio Streaming (Left aligned) */}
          <div className="story-editorial-wrapper align-left" id="story-text-3">
            <div className="story-editorial-card">
              <div className="story-badge gold">
                <span>🎙️ ACT 03 · VOICE STREAMING</span>
              </div>
              <h2 className="story-headline">
                Low-Latency Voice AI.<br />
                <span className="text-glow-gold">Sub-Second Turnaround.</span>
              </h2>
              <p className="story-copy">
                Full-duplex WebSocket pipeline integrating Whisper STT, streaming LLM inference, and neural voice
                synthesis with Voice Activity Detection (VAD). Powers 5 concurrent channels with 0 human handoff.
              </p>
              <div className="story-highlight-stats">
                <div>
                  <span className="story-stat-num text-glow-gold">&lt;400ms</span>
                  <span className="story-stat-label">End-to-End Latency</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-emerald">5 Streams</span>
                  <span className="story-stat-label">Concurrent / Node</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-cyan">100%</span>
                  <span className="story-stat-label">Autonomous Booking</span>
                </div>
              </div>
            </div>
          </div>

          {/* Act 4: Generative Video Studio (Top/Center aligned) */}
          <div className="story-editorial-wrapper align-center" id="story-text-4" style={{ top: '10%' }}>
            <div className="story-editorial-card" style={{ maxWidth: '640px' }}>
              <div className="story-badge blue">
                <span>🎬 ACT 04 · MULTIMODAL GENAI</span>
              </div>
              <h2 className="story-headline" style={{ fontSize: '1.95rem' }}>
                Agentic Video Studio.<br />
                <span className="text-glow-cyan">Script-to-Screen via Google Veo.</span>
              </h2>
              <p className="story-copy" style={{ marginBottom: '14px' }}>
                A 4-agent LangGraph workflow linking Director, Storyboard, Google Veo, and automated QA agents to synthesize
                commercial video campaigns with strict style and character continuity, compressing production by 80%.
              </p>
              <div className="story-highlight-stats" style={{ justifyContent: 'center' }}>
                <div>
                  <span className="story-stat-num text-glow-cyan">80%</span>
                  <span className="story-stat-label">Cycle Time Cut</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-gold">Google Veo</span>
                  <span className="story-stat-label">Motion Synthesis</span>
                </div>
                <div>
                  <span className="story-stat-num text-glow-emerald">4 Agents</span>
                  <span className="story-stat-label">Continuous DAG</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
